const output = [];

for (const item of $input.all()) {
  const binaries = item.binary || {};

  for (const key of Object.keys(binaries)) {
    output.push({
      json: {
        ...item.json,
        fileKey: key   // ÃƒÆ’Ã‚Â°Ãƒâ€¦Ã‚Â¸ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒâ€šÃ‚Â¥ VERY USEFUL for tracking
      },
      binary: {
        data: binaries[key]
      }
    });
  }
}

return output;

return $input.all().flatMap(item => {
  const data = item.json;
  const chunks = [];

  if (!data.semanticContent || typeof data.semanticContent !== "string") return [];

  const text = data.semanticContent
    .replace(/Project Name:.*\n/, "")
    .replace(/Document Name:.*\n/, "")
    .replace(/Document Type:.*\n/, "")
    .replace(/Source Format:.*\n/, "");

  const lines = text.split(/\n/g).map(l => l.trim()).filter(l => l);

  let currentSection = [];
  let sectionIndex = 0;
  let sectionTitle = "";

  const chunkSize = 10000;
  const overlap = 2000;
  const minChunkSize = 200;

  const headingRegex =
    /^(\d+(\.\d+)*\s+.*|[A-Z]{1,3}-\d+\s+.*|[A-Z][A-Za-z\s]{3,50}:?)$/;

  const safeString = value => String(value ?? '').trim();
  const metadataText = value => safeString(value).replace(/\s+/g, ' ').slice(0, 500);
  const metadataNumber = value => {
    const number = Number(value);
    return Number.isFinite(number) ? number : 0;
  };
  const normalizeDocType = value => {
    const text = safeString(value).toUpperCase().replace(/[^A-Z0-9]+/g, '_').replace(/^_+|_+$/g, '');
    return text || 'UNKNOWN';
  };

  function extractImageId(chunkText) {
    const match = chunkText.match(/Image ID:\s*(.+)/i);
    return match ? match[1].trim() : null;
  }

  function detectContentSource(sectionText, imageId) {
    const mode = safeString(data.contentMode).toLowerCase();
    const hasImageEvidence = Boolean(imageId) || /IMAGE-DERIVED INSIGHTS|IMAGE CONTEXT START|Extracted Insights:/i.test(sectionText);
    if (mode === "image-only") return "image";
    if (mode === "hybrid" && hasImageEvidence) return "image";
    return "text";
  }

  function buildMetadata(sectionText, chunkText, chunkIndex) {
    const imageId = extractImageId(chunkText);
    const contentSource = detectContentSource(chunkText, imageId);
    const docType = normalizeDocType(data.docType || "UNKNOWN");
    const project = data.projectName || "unknown";
    const fileName = data.fileName || data.filename || "unknown";
    const sourceFormat = data.sourceFormat || data.fileType || "unknown";
    const compositeKey = `${project}|${docType}|${contentSource}`;
    const chunkId = [
      data.documentId || fileName,
      sectionIndex,
      chunkIndex,
      contentSource
    ].map(value => safeString(value).replace(/[^A-Za-z0-9_-]+/g, '-')).join('|');

    return {
      project,
      projectId: data.projectId || null,
      requestedBy: data.requestedBy || null,
      settingsVersion: data.settingsVersion || null,
      environment: data.environmentKey || 'local',
      chromaCollection: data.configSnapshot?.chroma?.collection || 'qa-chunks-batches',

      jobId: data.jobId || null,
      status: data.status || null,
      documentId: data.documentId || "unknown",
      docType,
      documentTypeOriginal: metadataText(data.documentTypeOriginal || ''),
      documentCategory: data.documentCategory || "unclassified",
      artifactType: data.artifactType || "unclassified_document",
      metadataConfidence: metadataNumber(data.metadataConfidence),
      metadataSource: data.metadataSource || "fallback_unknown",

      fileName,
      filename: fileName,
      fileType: data.fileType || "unknown",
      sourceFormat,
      pageCount: metadataNumber(data.pageCount),

      contentMode: data.contentMode || "unknown",
      containsImages: Boolean(data.containsImages),
      containsText: Boolean(data.containsText),
      hasVisionContent: /IMAGE-DERIVED INSIGHTS|IMAGE CONTEXT START|Extracted Insights:/i.test(sectionText),

      sectionTitle: sectionTitle || `Section ${sectionIndex}`,
      sectionIndex,
      structuralType: "logical_section",
      chunkIndex,
      chunkId,

      imageId: imageId || null,
      contentSource,
      compositeKey
    };
  }

  function buildChunks(sectionText) {
    const result = [];

    if (sectionText.length <= chunkSize) {
      if (sectionText.trim().length >= minChunkSize) {
        result.push({
          json: {
            pageContent: sectionText,
            metadata: buildMetadata(sectionText, sectionText, 0)
          }
        });
      }

      return result;
    }

    for (let i = 0; i < sectionText.length; i += (chunkSize - overlap)) {
      const chunkText = sectionText.slice(i, i + chunkSize);

      if (chunkText.trim().length < minChunkSize) break;

      const chunkIndex = Math.floor(i / (chunkSize - overlap));
      result.push({
        json: {
          pageContent: chunkText,
          metadata: buildMetadata(sectionText, chunkText, chunkIndex)
        }
      });
    }

    return result;
  }

  lines.forEach(line => {
    if (headingRegex.test(line)) {
      if (currentSection.length) {
        const sectionText = currentSection.join("\n").trim();
        if (sectionText) {
          chunks.push(...buildChunks(sectionText));
        }
      }
      sectionIndex++;
      sectionTitle = line;
      currentSection = [line];
    } else {
      currentSection.push(line);
    }
  });

  if (currentSection.length) {
    const sectionText = currentSection.join("\n").trim();
    if (sectionText) {
      chunks.push(...buildChunks(sectionText));
    }
  }

  return chunks;
});

return $input.all().flatMap(item => {
  const data = item.json;

  if (!data.images || data.images.length === 0) {
    return [];
  }

  return data.images.map((img, index) => ({
    json: {
      projectName: data.projectName,
      status: data.status,
      jobId: data.jobId,
      parentFileName: data.fileName,
      imageFileName: img.fileName,   // ÃƒÆ’Ã‚Â¢Ãƒâ€¦Ã¢â‚¬Å“ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ important
      imageId: img.imageId || `${data.fileName}_${index}`, // ÃƒÆ’Ã‚Â¢Ãƒâ€¦Ã¢â‚¬Å“ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ SAFE FALLBACK
      imageIndex: index,
      base64: img.base64
    }
  }));
});

const visionOutputs = $input.all();
const originalItems = $items("Prepare Vision Payload");

function readUsage(json) {
  const usage =
    json.usage ||
    json.response?.usage ||
    json.output?.usage ||
    json.output?.[0]?.usage ||
    json.llmUsage ||
    {};

  const inputTokens =
    Number(usage.input_tokens) ||
    Number(usage.prompt_tokens) ||
    Number(usage.inputTokens) ||
    Number(usage.promptTokens) ||
    0;

  const outputTokens =
    Number(usage.output_tokens) ||
    Number(usage.completion_tokens) ||
    Number(usage.outputTokens) ||
    Number(usage.completionTokens) ||
    0;

  return { inputTokens, outputTokens };
}

const results = [];

for (const vision of visionOutputs) {
  const rawText =
    vision.json.output?.[0]?.content?.[0]?.text ||
    vision.json.output_text ||
    '';

  const imageDescription = rawText.trim();
  const pairedIndex = vision.pairedItem?.item;
  const original = originalItems[pairedIndex];

  if (!original) continue;

  const usage = readUsage(vision.json || {});
  const estimatedOutputTokens = usage.outputTokens || Math.ceil(imageDescription.length / 4);
  const meta = original.json;

  results.push({
    json: {
      projectName: meta.projectName,
      status: meta.status,
      jobId: meta.jobId,
      imageIndex: meta.imageIndex,
      imageId: meta.imageId,
      imageFileName: meta.imageFileName,
      parentFileName: meta.parentFileName,
      imageDescription,
      totalImagesInDocument: meta.totalImagesInDocument || null,
      imageLimitApplied: meta.imageLimitApplied || false,
      visionTokensInput: usage.inputTokens,
      visionTokensOutput: estimatedOutputTokens,
      visionTokensTotal: usage.inputTokens + estimatedOutputTokens,
      visionUsageEstimated: !usage.inputTokens && !usage.outputTokens
    }
  });
}

return results;

const originalDocs = $items("Extract Text + Image");
const visionResults = $input.all();

const visionMap = {};
const usageMap = {};

for (const item of visionResults) {
  const { imageId, imageDescription } = item.json;
  visionMap[imageId] = imageDescription;
  usageMap[imageId] = {
    input: Number(item.json.visionTokensInput) || 0,
    output: Number(item.json.visionTokensOutput) || 0,
    total: Number(item.json.visionTokensTotal) || 0,
    estimated: Boolean(item.json.visionUsageEstimated)
  };
}

const VISION_INPUT_PER_TOKEN = 0.15 / 1_000_000;
const VISION_OUTPUT_PER_TOKEN = 0.60 / 1_000_000;

return originalDocs.map(doc => {
  const data = doc.json;

  if (!data.images || data.images.length === 0) {
    return {
      json: {
        ...data,
        visionTokensInput: 0,
        visionTokensOutput: 0,
        visionTokensTotal: 0,
        visionCostUsd: 0,
        visionUsageEstimated: false
      }
    };
  }

  let visionTokensInput = 0;
  let visionTokensOutput = 0;
  let visionUsageEstimated = false;

  const updatedImages = data.images.map(img => {
    const usage = usageMap[img.imageId] || {};
    visionTokensInput += Number(usage.input) || 0;
    visionTokensOutput += Number(usage.output) || 0;
    visionUsageEstimated = visionUsageEstimated || Boolean(usage.estimated);
    return {
      imageFileName: img.fileName,
      imageId: img.imageId,
      imageDescription: visionMap[img.imageId] || null,
      visionTokensInput: Number(usage.input) || 0,
      visionTokensOutput: Number(usage.output) || 0,
      visionTokensTotal: Number(usage.total) || 0,
      visionUsageEstimated: Boolean(usage.estimated)
    };
  });

  const visionCostUsd =
    (visionTokensInput * VISION_INPUT_PER_TOKEN) +
    (visionTokensOutput * VISION_OUTPUT_PER_TOKEN);

  return {
    json: {
      ...data,
      images: updatedImages,
      visionTokensInput,
      visionTokensOutput,
      visionTokensTotal: visionTokensInput + visionTokensOutput,
      visionCostUsd: Number(visionCostUsd.toFixed(6)),
      visionUsageEstimated
    }
  };
});

return $input.all().map(item => {
  const d = item.json;

  const safeString = value => String(value ?? '').trim();
  const compact = value => safeString(value).replace(/\s+/g, ' ');
  const normalizeFormat = value => safeString(value || 'unknown').replace(/^\./, '').toLowerCase() || 'unknown';

  const normalizeDocTypeValue = value => {
    const raw = safeString(value);
    if (!raw) return null;
    const key = raw.toUpperCase().replace(/[^A-Z0-9]+/g, '_').replace(/^_+|_+$/g, '');
    const aliases = {
      BUSINESS_REQUIREMENTS: 'BRD',
      BUSINESS_REQUIREMENT_DOCUMENT: 'BRD',
      BRD: 'BRD',
      FUNCTIONAL_REQUIREMENTS: 'FRD',
      FUNCTIONAL_REQUIREMENT_DOCUMENT: 'FRD',
      FRD: 'FRD',
      PRODUCT_REQUIREMENTS: 'PRD',
      PRODUCT_REQUIREMENT_DOCUMENT: 'PRD',
      PRD: 'PRD',
      SOFTWARE_REQUIREMENTS_SPECIFICATION: 'SRS',
      SRS: 'SRS',
      HIGH_LEVEL_DESIGN: 'HLD',
      HLD: 'HLD',
      LOW_LEVEL_DESIGN: 'LLD',
      LLD: 'LLD',
      UI_UX: 'UI_UX',
      UX_UI: 'UI_UX',
      WIREFRAME: 'UI_UX',
      WIREFRAMES: 'UI_UX',
      TRANSCRIPT: 'TRANSCRIPT',
      MEETING_TRANSCRIPT: 'TRANSCRIPT',
      TEST_CASE: 'TEST_CASES',
      TEST_CASES: 'TEST_CASES',
      TEST_PLAN: 'TEST_PLAN',
      QA_PLAN: 'TEST_PLAN',
      API: 'API_SPEC',
      API_SPEC: 'API_SPEC',
      OPENAPI: 'API_SPEC',
      SWAGGER: 'API_SPEC',
      DATA_MODEL: 'DATA_MODEL',
      ERD: 'DATA_MODEL',
      ARCHITECTURE: 'ARCHITECTURE',
      UNKNOWN: null
    };
    return aliases[key] || null;
  };

  const classifyByText = value => {
    const text = safeString(value).toLowerCase();
    if (!text) return null;
    const tests = [
      ['BRD', /\b(brd|business requirements?|business requirement document|business rules?|business objective|stakeholder requirements?)\b/i],
      ['FRD', /\b(frd|functional requirements?|functional requirement document|functional specification|system shall|the application shall)\b/i],
      ['PRD', /\b(prd|product requirements?|product requirement document|product goals?|product scope)\b/i],
      ['SRS', /\b(srs|software requirements specification|system requirements specification)\b/i],
      ['HLD', /\b(hld|high level design|solution architecture|logical architecture|architecture overview)\b/i],
      ['LLD', /\b(lld|low level design|detailed design|class design|sequence diagram|component design)\b/i],
      ['UI_UX', /\b(ui\/ux|ux\/ui|wireframes?|mockups?|prototype|figma|screen design|user interface|user journey|navigation flow)\b/i],
      ['TRANSCRIPT', /\b(transcript|meeting notes|workshop|discussion|interview|q&a|question and answer|minutes of meeting)\b/i],
      ['TEST_CASES', /\b(test cases?|test suite|test scenarios?|expected result|actual result|precondition)\b/i],
      ['TEST_PLAN', /\b(test plan|qa strategy|test strategy|test approach|test scope)\b/i],
      ['API_SPEC', /\b(api specification|openapi|swagger|endpoint|request payload|response payload|rest api|graphql)\b/i],
      ['DATA_MODEL', /\b(data model|database schema|erd|entity relationship|table structure|data dictionary)\b/i],
      ['ARCHITECTURE', /\b(architecture|deployment topology|infrastructure|non functional architecture|integration architecture)\b/i]
    ];
    for (const [docType, pattern] of tests) {
      if (pattern.test(text)) return docType;
    }
    return null;
  };

  const docTypeCategory = docType => ({
    BRD: 'business_requirements',
    PRD: 'business_requirements',
    FRD: 'functional_requirements',
    SRS: 'functional_requirements',
    HLD: 'technical_design',
    LLD: 'technical_design',
    ARCHITECTURE: 'technical_design',
    API_SPEC: 'technical_design',
    DATA_MODEL: 'technical_design',
    UI_UX: 'user_experience',
    TRANSCRIPT: 'stakeholder_conversation',
    TEST_CASES: 'quality_assurance',
    TEST_PLAN: 'quality_assurance',
    UNKNOWN: 'unclassified'
  }[docType] || 'unclassified');

  const docTypeArtifact = docType => ({
    BRD: 'business_requirements_document',
    PRD: 'product_requirements_document',
    FRD: 'functional_requirements_document',
    SRS: 'software_requirements_specification',
    HLD: 'high_level_design',
    LLD: 'low_level_design',
    ARCHITECTURE: 'architecture_document',
    API_SPEC: 'api_specification',
    DATA_MODEL: 'data_model',
    UI_UX: 'ui_ux_artifact',
    TRANSCRIPT: 'meeting_transcript',
    TEST_CASES: 'test_cases',
    TEST_PLAN: 'test_plan',
    UNKNOWN: 'unclassified_document'
  }[docType] || 'unclassified_document');

  const explicitDocType =
    normalizeDocTypeValue(d.docType) ||
    normalizeDocTypeValue(d.documentType) ||
    normalizeDocTypeValue(d.document_type);

  const filenameDocType = classifyByText(d.fileName || d.fileKey || '');
  const imageText = Array.isArray(d.images)
    ? d.images.map(img => img.imageDescription || img.fileName || '').join('\n')
    : '';
  const contentDocType = classifyByText([
    d.rawText || '',
    imageText
  ].join('\n').slice(0, 12000));

  let docType = 'UNKNOWN';
  let metadataSource = 'fallback_unknown';
  let metadataConfidence = 0.2;

  if (explicitDocType) {
    docType = explicitDocType;
    metadataSource = 'upstream_doc_type';
    metadataConfidence = 0.95;
  } else if (filenameDocType) {
    docType = filenameDocType;
    metadataSource = 'filename_classifier';
    metadataConfidence = 0.78;
  } else if (contentDocType) {
    docType = contentDocType;
    metadataSource = 'content_classifier';
    metadataConfidence = 0.68;
  }

  const sourceFormat = normalizeFormat(d.fileType || d.fileExtension || d.extension);
  const documentCategory = docTypeCategory(docType);
  const artifactType = docTypeArtifact(docType);
  const documentTypeOriginal = compact(d.docType || d.documentType || d.document_type || '');

  let combined = '';

  combined += `Project Name: ${d.projectName}\n`;
  combined += `Document Name: ${d.fileName}\n`;
  combined += `Document Type: ${docType}\n`;
  combined += `Source Format: ${sourceFormat}\n\n`;

  if (d.rawText && d.rawText.trim().length > 0) {
    combined += '===== DOCUMENT TEXT =====\n';
    combined += d.rawText.trim() + '\n\n';
  }

  if (d.images && d.images.length > 0) {
    const validImages = d.images.filter(img => img.imageDescription);

    if (validImages.length > 0) {
      combined += '===== IMAGE-DERIVED INSIGHTS =====\n\n';

      for (const img of validImages) {
        combined += `--- IMAGE CONTEXT START ---\n`;
        combined += `Image Name: ${img.imageFileName}\n`;
        combined += `Image ID: ${img.imageId}\n\n`;
        combined += `Extracted Insights:\n`;
        combined += img.imageDescription + '\n\n';
        combined += `--- IMAGE CONTEXT END ---\n\n`;
      }
    }
  }

  const trigger = $('When Executed by Another Workflow').first().json;
  const configSnapshot = d.configSnapshot || trigger.configSnapshot || trigger.config_snapshot || {};

  return {
    json: {
      projectName: d.projectName,
      status: d.status,
      jobId: d.jobId,
      fileName: d.fileName,
      filename: d.fileName,
      fileType: d.fileType,
      sourceFormat,
      pageCount: d.pageCount,
      docType,
      documentTypeOriginal,
      documentCategory,
      artifactType,
      metadataConfidence,
      metadataSource,
      documentId: d.documentId,
      contentMode: d.contentMode,
      containsText: d.containsText,
      containsImages: d.containsImages,
      semanticContent: combined.trim(),
      visionTokensInput: Number(d.visionTokensInput) || 0,
      visionTokensOutput: Number(d.visionTokensOutput) || 0,
      visionTokensTotal: Number(d.visionTokensTotal) || 0,
      visionCostUsd: Number(d.visionCostUsd) || 0,
      visionUsageEstimated: Boolean(d.visionUsageEstimated),
      projectId: d.projectId || trigger.projectId || trigger.project_id || null,
      requestedBy: d.requestedBy || trigger.requestedBy || trigger.requested_by || null,
      settingsVersion: d.settingsVersion || trigger.settingsVersion || trigger.settings_version || null,
      configSnapshot,
      environmentKey: configSnapshot.environment?.key || d.environment || 'local'
    }
  };
});

